import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {stripTypeScriptTypes} from 'node:module';
import {runInNewContext} from 'node:vm';
import * as model from '../web/src/model.ts';
const source=stripTypeScriptTypes((await readFile(new URL('../web/src/features/Approvals.words.ts',import.meta.url),'utf8')).replace(/^import .*;\n/gm,'').replace(/^export \{.*\} from .*;\n/gm,'')).replace(/^export /gm,'');
const words=runInNewContext(source+"\n({myAgent,myAgentSeed,remoteNeedsHumanDetail:typeof remoteNeedsHumanDetail==='function'?remoteNeedsHumanDetail:null})",{...model});
const host='owner/bezos',local='owner/zenbook',id='request',key='verified-key',attempt=2;
const m={id,from:'owner/linux-laptop',to:host,dir:'out',kind:'question',body:'Who is Bernard?',author:{},history:true,exec:{host,state:'needs_human',attempt,detail:'needs_human'},continuation:{host,id,key,attempt}};
const person={person:'own',address:local,devices:[{address:local},{address:host},{address:m.from}]};
const base={me:{address:local,agent:true},person,review:[]};
assert.equal(words.myAgent(m,{},base).address,host,'remote execution must not become the local agent');
assert.equal(words.myAgentSeed(m,base),host);
assert.equal(words.myAgent({...m,continuation:undefined,exec:undefined},{},base).address,local,'local fallback unchanged');
assert.equal(words.myAgent({...m,target:{address:'owner/named',agent_id:'named'}},{named:'Named'},base).address,'owner/named','explicit target takes precedence');
const item={id,key,attempt,kind:'question',state:'needs_human',excerpt:'Professional memory unavailable; provide a surname.'};
const notice=(items,at=100,received='2026-10-11T11:44:00Z')=>({id:'notice',peer:host,notice:true,at:received,report:{v:2,host,at,items}});
const overview=(notices)=>({...base,review:notices});
assert.equal(words.remoteNeedsHumanDetail(m,overview([notice([item])])),item.excerpt);
for(const changed of [{id:'other'},{key:'other'},{attempt:3},{state:'answered'},{conv:true},{kind:'task'}])
 assert.equal(words.remoteNeedsHumanDetail(m,overview([notice([{...item,...changed}])])),'','different exact request never supplies detail');
assert.equal(words.remoteNeedsHumanDetail(m,overview([{...notice([item]),peer:'owner/other'}])),'');
assert.equal(words.remoteNeedsHumanDetail(m,overview([{...notice([item]),report:{...notice([item]).report,host:'owner/other'}}])),'');
assert.equal(words.remoteNeedsHumanDetail(m,overview([notice([item],100),notice([],'1970-01-01T00:01:41Z')])),'','browser ISO snapshot supersedes numeric seconds');
assert.equal(words.remoteNeedsHumanDetail(m,overview([notice([item]),notice([],101)])),'','newer empty snapshot suppresses old reason');
assert.equal(words.remoteNeedsHumanDetail(m,overview([notice([item]),notice([],100,'2026-10-11T11:43:59Z')])),'','same-timestamp settled empty wins');
assert.equal(words.remoteNeedsHumanDetail(m,overview([notice([item]),notice([{...item,key:'other'}],101)])),'','no fallback into an older matching snapshot');
assert.equal(words.remoteNeedsHumanDetail({...m,exec:{...m.exec,state:'answered'}},overview([notice([item])])),'','terminal card never retains old blocker');
assert.equal(words.remoteNeedsHumanDetail({...m,continuation:undefined},overview([notice([item])])),'','no inferred continuation authority');
assert.deepEqual(m.continuation,{host,id,key,attempt},'presentation preserves exact reply/resolve binding');
console.log('Remote needs-human host and exact latest report detail PASS');
